"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[8511],{8880:o=>{o.exports=JSON.parse('{"tag":{"label":"Curl","permalink":"/docs/tags/curl","allTagsPath":"/docs/tags","count":5,"items":[{"id":"Workbooks/Append or replace data in workbooks","title":"Append or replace data in workbooks","description":"You can append new data to existing workbooks or replace entire sheets with revised data. If you need to do any of the following, then appending the workbook with the required data or replacing the entire workbook is a good solution:","permalink":"/docs/Workbooks/append-replace-data-existing-workbooks"},{"id":"Workbooks/Column Extraction","title":"Column Extraction","description":"The Column Extraction feature enables you to automatically extract structured data fields from unstructured sources \u2014 such as meeting transcripts, recorded calls, or text documents \u2014 using an AI agent. Rather than manually reviewing lengthy content, you can configure an extraction pipeline that pulls specific fields into a structured workbook with minimal effort.","permalink":"/docs/Workbooks/column-extraction"},{"id":"Workbooks/Creating links and joins in dynamic tables","title":"Creating links and joins in dynamic tables","description":"If you want to connect to specific records from another workbook in DataGOL, you create a Link. A Link is a direct relationship created between two different tables or workbooks. This is done by adding a specific column to a workbook and then manually or automatically connecting it to records in another workbook. Links are about connecting records and viewing related data within an existing workbook. They add a column to your current table.","permalink":"/docs/Workbooks/create-link-joins-dynamic tables"},{"id":"Workbooks/Workbook API reference","title":"Workbook API reference","description":"Overview","permalink":"/docs/Workbooks/workbook-api-reference"},{"id":"Workbooks/Workbook as a MCP","title":"Workbook MCP (Model Context Protocol)","description":"Overview","permalink":"/docs/Workbooks/workbook-as-a-MCP"}],"unlisted":false}}')}}]);